import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * Narrows the customer list by name and by status.
 *
 * <p>A customer matches when it satisfies both parts:
 * <ul>
 *   <li>the name text is split on whitespace into terms, and every term must be
 *       a substring of the first name or of the last name, ignoring case and
 *       accents;</li>
 *   <li>the status set is empty (every status matches) or contains the
 *       customer's status.</li>
 * </ul>
 *
 * @param name     the text typed into the name filter; may be blank
 * @param statuses the statuses to keep; empty means every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter NONE = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
    }

    /**
     * Returns a predicate for this filter. The name terms are normalized once
     * here, not once per customer.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = nameTerms();
        Set<CustomerStatus> wanted = statuses;
        return customer -> (wanted.isEmpty() || wanted.contains(customer.status()))
                && matchesEveryTerm(customer, terms);
    }

    private List<String> nameTerms() {
        return WHITESPACE.splitAsStream(fold(name))
                .filter(term -> !term.isEmpty())
                .toList();
    }

    private static boolean matchesEveryTerm(Customer customer, List<String> terms) {
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    /** Lower-cases and strips accents, so that {@code Mäkinen} folds to {@code makinen}. */
    static String fold(String text) {
        String lowered = text.toLowerCase(Locale.ROOT);
        String decomposed = Normalizer.normalize(lowered, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
    }
}
